import os,sys
sys.path.insert(0,os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from common import *
N='#1b2a4a'
# targeting: radius/city allowed vs zip not
def mapsvg(kind):
    base='<svg width="560" height="360" viewBox="0 0 560 360"><rect width="560" height="360" fill="#e9efe6"/><path d="M0 120H560M0 250H560M140 0V360M300 0V360M450 0V360" stroke="#fff" stroke-width="14"/><path d="M0 330L560 40" stroke="#f6e4a8" stroke-width="12"/><rect x="170" y="140" width="110" height="90" fill="#d6e6f5"/>'
    if kind=='ok': base+='<circle cx="290" cy="190" r="130" fill="#14808a" fill-opacity=".18" stroke="#14808a" stroke-width="5"/><circle cx="290" cy="190" r="10" fill="#d93025"/>'
    else: base+='<g fill="#c2410c" fill-opacity=".18" stroke="#c2410c" stroke-width="4" stroke-dasharray="10 6"><path d="M100 70L300 50L330 170L120 190Z"/><path d="M330 170L520 150L500 300L340 310Z"/><path d="M120 190L330 170L340 310L130 320Z"/></g><g font-family="Inter" font-weight="800" font-size="20" fill="#c2410c"><text x="170" y="130">ZIP A</text><text x="390" y="240">ZIP B</text><text x="190" y="260">ZIP C</text></g>'
    return base+'</svg>'
def panel(x,col,bg,tag,m,head,lines):
    return ('<div class="paper sh" style="left:%dpx;top:120px;width:640px;height:560px;border-radius:14px;border:4px solid %s"><div style="background:%s;padding:16px 26px"><span class="chip" style="background:%s;color:#fff">%s</span></div>'%(x,col,bg,col,tag)
      +'<div style="margin:18px auto 0;width:560px">'+m+'</div><div style="padding:14px 26px"><div style="font-size:24px;font-weight:800;color:'+N+'">'+head+'</div><div style="font-size:19px;color:#475467;margin-top:6px;line-height:1.4">'+lines+'</div></div></div>')
gads_targeting=page(panel(110,'#1f8a5b','#e6f6ee','Allowed',mapsvg('ok'),'City, or a radius around a location','Radius targeting needs at least 1 km around a point.')+panel(850,'#b42318','#fdecea','Not allowed',mapsvg('zip'),'ZIP code targeting','Also not allowed: age, gender, parental status, marital status.')+'<div class="abs" style="left:110px;top:730px;width:1380px;font-size:22px;font-weight:600;color:'+N+'">For US real estate ads under Google&rsquo;s housing policy. Check the current policy before you build a campaign.</div>','Radius targeting vs ZIP code targeting',note='')
# search -> ad -> landing page
q=('<div class="abs" style="left:70px;top:150px;width:470px"><div style="font-size:15px;font-weight:800;color:#667085;letter-spacing:.1em;margin-bottom:10px">1. A SELLER SEARCHES</div><div style="border:2px solid #d0d5dd;border-radius:999px;padding:14px 24px;font-size:21px;background:#fff">what is my home worth in Cedar Hills</div></div>')
ad=('<div class="abs" style="left:620px;top:150px;width:470px"><div style="font-size:15px;font-weight:800;color:#667085;letter-spacing:.1em;margin-bottom:10px">2. YOUR AD APPEARS</div><div class="paper sh" style="position:relative;border-radius:12px;padding:22px 26px"><div style="font-size:14px;color:#667085;font-weight:700;margin-bottom:8px"><span style="border:1px solid #98a2b3;border-radius:4px;padding:1px 6px;margin-right:8px">Ad</span>example.com/home-value</div><div style="font-size:25px;color:#1a56db;font-weight:600;line-height:1.25">What Is Your Home Worth Today?</div><div style="font-size:18px;color:#1d2433;margin-top:8px;line-height:1.45">Free home value review for Cedar Hills homeowners. Request it in two minutes.</div></div></div>')
land=('<div class="abs sh" style="left:1160px;top:150px;width:370px;height:420px;border-radius:12px;background:#fff;overflow:hidden"><div style="height:34px;background:#e9edf3;padding:9px 14px;font-size:13px;color:#667085">example.com/home-value</div><div style="padding:22px"><div class="serif" style="font-size:25px;font-weight:700;color:'+N+';line-height:1.2">What is your Cedar Hills home worth?</div><div style="font-size:16px;color:#475467;margin:10px 0 16px;line-height:1.4">Tell us where it is and where to send the review.</div><div style="border:1px solid #d0d5dd;border-radius:8px;padding:10px 12px;font-size:16px;color:#98a2b3;margin-bottom:10px">Home address</div><div style="border:1px solid #d0d5dd;border-radius:8px;padding:10px 12px;font-size:16px;color:#98a2b3;margin-bottom:14px">Phone or email</div><div style="background:#e0613a;color:#fff;font-weight:800;text-align:center;border-radius:8px;padding:12px;font-size:17px">Request my review</div><div style="margin-top:14px;font-size:14px;color:#667085">Call 555-0142</div></div></div>')
lab3='<div class="abs" style="left:1160px;top:116px;font-size:15px;font-weight:800;color:#667085;letter-spacing:.1em">3. THE PAGE MATCHES THE OFFER</div>'
arrows=''.join('<div class="abs" style="left:%dpx;top:200px;font-size:38px;color:#98a2b3;font-weight:800">&rarr;</div>'%x for x in (555,1110))
gads_search=page(q+ad+lab3+land+arrows+'<div class="abs" style="left:70px;top:420px;width:1000px;font-size:23px;color:'+N+';font-weight:600;line-height:1.5">One search, one offer, one page. A seller who asks what a home is worth should land on a home valuation request, not your home page.</div>','Match the search, the ad and the page',note='Sample ad and page. Names are made up.')
# four weeks
W=[('Week one','Pick one offer and one city or radius. One ad group around three to five specific searches, two ad versions, a small daily budget.','#14808a'),('Week two','Read the search terms report, add negative keywords, pause searches that get clicks but no contacts.','#1b2a4a'),('Week three','Improve the landing page from what visitors did: shorten the form, move the phone number higher.','#7c5cc4'),('Week four','Count paid leads, appointments and cost per lead. Scale, change the offer, or stop.','#e0613a')]
c=''
for i,(a,b,col) in enumerate(W):
    x=60+i*375
    c+='<div class="paper sh" style="left:%dpx;top:150px;width:350px;height:330px;border-radius:14px"><div style="background:%s;color:#fff;padding:18px 24px;font-size:26px;font-weight:800">%s</div><div style="padding:22px 24px;font-size:21px;color:#1d2433;line-height:1.45">%s</div></div>'%(x,col,a,b)
gads_weeks=page(c+'<div class="abs" style="left:60px;top:520px;width:1480px;font-size:23px;font-weight:600;color:'+N+';line-height:1.5">Keep a note of what you changed each week. Changing five things at once teaches nothing.</div>','A four-week test for Google Ads',note='')
SC=dict(gads_targeting=gads_targeting,gads_search=gads_search,gads_weeks=gads_weeks)
if __name__=='__main__': render(sel(sys.argv,SC))
